// Crawlable pages generated by the Worker: a sitemap and one small share page
// per public drawing. They read only marks that have not been hidden.
import { INKS, ENVIRONMENTS } from "../public/environments.js";

export const SITE = "https://sloppworld.com";
export const OG_IMAGE = `${SITE}/og-image.png`;
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const SITEMAP_LIMIT = 49000;

const escape = (value) => String(value).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);
const html = (body, status = 200) => new Response(body, { status, headers: { "content-type": "text/html; charset=utf-8", "cache-control": "public, max-age=300" } });

const sitemap = async (db) => {
  let marks = [];
  try {
    marks = (await db.prepare("SELECT id, created_at FROM marks WHERE hidden_at IS NULL ORDER BY seq DESC LIMIT ?").bind(SITEMAP_LIMIT).all()).results;
  } catch {}
  const url = (loc, lastmod) => `<url><loc>${escape(loc)}</loc>${lastmod ? `<lastmod>${escape(lastmod.slice(0, 10))}</lastmod>` : ""}</url>`;
  const body = `<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n${[url(`${SITE}/`, marks[0]?.created_at), ...marks.map((m) => url(`${SITE}/d/${m.id}`, m.created_at))].join("\n")}\n</urlset>\n`;
  return new Response(body, { headers: { "content-type": "application/xml; charset=utf-8", "cache-control": "public, max-age=3600" } });
};

// A flat, front-facing sketch of the drawing's strokes. Depth and motion are left to the world.
export const previewSvg = (strokes) => {
  const points = strokes.flatMap((s) => s.points);
  if (!points.length) return "";
  const xs = points.map((p) => p[0]), ys = points.map((p) => p[1]);
  const left = Math.min(...xs), top = Math.min(...ys);
  const width = Math.max(Math.max(...xs) - left, 1), height = Math.max(Math.max(...ys) - top, 1);
  const pad = Math.max(width, height) * 0.08, weight = Math.max(width, height) / 180;
  const lines = strokes.map((s) => `<polyline fill="none" stroke="${INKS[s.ink] || INKS.ink}" stroke-width="${weight.toFixed(2)}" stroke-linecap="round" stroke-linejoin="round" points="${s.points.map((p) => `${(+p[0]).toFixed(1)},${(+p[1]).toFixed(1)}`).join(" ")}"/>`).join("");
  return `<svg role="img" aria-label="A sketch of this drawing" viewBox="${(left - pad).toFixed(1)} ${(top - pad).toFixed(1)} ${(width + pad * 2).toFixed(1)} ${(height + pad * 2).toFixed(1)}">${lines}</svg>`;
};

const page = ({ title, description, canonical, body, robots = "index,follow" }) => `<!doctype html>
<html lang="en"><head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#f0e8d9">
<title>${escape(title)}</title><meta name="description" content="${escape(description)}"><meta name="robots" content="${robots}">
${canonical ? `<link rel="canonical" href="${escape(canonical)}"><meta property="og:url" content="${escape(canonical)}">` : ""}
<meta property="og:site_name" content="slopp"><meta property="og:type" content="article"><meta property="og:title" content="${escape(title)}"><meta property="og:description" content="${escape(description)}">
<meta property="og:image" content="${OG_IMAGE}"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta property="og:image:alt" content="slopp, a shared world of moving drawings">
<meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="${escape(title)}"><meta name="twitter:description" content="${escape(description)}"><meta name="twitter:image" content="${OG_IMAGE}">
<link rel="icon" href="/favicon.svg" type="image/svg+xml">
<style>body{margin:0;min-height:100vh;display:grid;place-items:center;background:#f0e8d9;color:#282429;font-family:Arial,Helvetica,sans-serif}main{max-width:560px;padding:48px 28px;text-align:center}h1{font-family:Georgia,serif;font-weight:400;font-size:clamp(30px,6vw,46px);letter-spacing:-1.5px;margin:12px 0 18px}.eyebrow{font-size:10px;letter-spacing:2px;color:#71695f}svg{width:min(420px,80vw);height:auto;max-height:50vh;margin:8px auto 24px;display:block}a.enter{display:inline-block;margin-top:22px;padding:13px 24px;border:1px solid #28242922;border-radius:30px;color:#282429;text-decoration:none}a.enter:hover{background:#28242910}p{color:#71695f;line-height:1.55}</style>
</head><body><main>${body}</main></body></html>`;

const sharePage = async (db, id) => {
  let row = null;
  try {
    row = UUID.test(id) ? await db.prepare("SELECT id, created_at, payload FROM marks WHERE id = ? AND hidden_at IS NULL").bind(id).first() : null;
  } catch {}
  if (!row) return html(page({ title: "slopp — this drawing is not here", description: "This drawing could not be found. The world of moving drawings is still open.", robots: "noindex", body: `<span class="eyebrow">SLOPP</span><h1>This drawing is not here.</h1><p>It may have drifted away. The rest of the world is still open.</p><a class="enter" href="/">Enter the world ↗</a>` }), 404);
  const payload = JSON.parse(row.payload);
  const place = ENVIRONMENTS.find((e) => e.id === payload.space?.environment)?.name;
  const date = new Date(row.created_at).toLocaleDateString("en-GB", { day: "numeric", month: "long", year: "numeric", timeZone: "UTC" });
  const title = "A drawing in slopp";
  const description = `Someone let this drawing go${place ? ` in ${place}` : ""} on ${date}. Find it moving in slopp, a shared world of drawings, and leave one of your own.`;
  const canonical = `${SITE}/d/${row.id}`;
  return html(page({ title, description, canonical, body: `<span class="eyebrow">ONE WORLD, MANY HANDS</span><h1>A drawing in slopp</h1>${previewSvg(payload.strokes)}<p>${escape(description)}</p><a class="enter" href="/?d=${row.id}">See it in the world ↗</a>
<script type="application/ld+json">${JSON.stringify({ "@context": "https://schema.org", "@type": "CreativeWork", name: title, url: canonical, dateCreated: row.created_at, license: "https://creativecommons.org/licenses/by/4.0/", creator: { "@type": "Organization", name: "slopp contributors" }, isPartOf: { "@type": "WebSite", name: "slopp", url: `${SITE}/` } }).replace(/</g, "\\u003c")}</script>` }));
};

export const handlePages = async (request, db) => {
  if (request.method !== "GET" && request.method !== "HEAD") return null;
  const { pathname } = new URL(request.url);
  if (pathname === "/sitemap.xml") return sitemap(db);
  const share = pathname.match(/^\/d\/([^/]+)\/?$/);
  if (share) return sharePage(db, share[1]);
  return null;
};
